import unittest

from solution import index_leaves


class IndexLeavesTests(unittest.TestCase):
    def test_depth_first_full_paths_and_insertion_order(self):
        tree = {
            "user": {
                "name": "Ada",
                "address": {"city": "London", "zip": 123},
            },
            "active": True,
        }
        result = index_leaves(tree)
        self.assertEqual(
            result,
            {
                "user.name": "Ada",
                "user.address.city": "London",
                "user.address.zip": 123,
                "active": True,
            },
        )
        self.assertEqual(
            list(result),
            ["user.name", "user.address.city", "user.address.zip", "active"],
        )

    def test_empty_dictionaries_contribute_no_entries(self):
        self.assertEqual(index_leaves({}), {})
        self.assertEqual(index_leaves({"empty": {}, "also": {"empty": {}}}), {})

    def test_leaf_values_are_deep_copied(self):
        leaf = [{"numbers": [1]}]
        tree = {"branch": {"leaf": leaf}}
        result = index_leaves(tree)
        self.assertEqual(result, {"branch.leaf": [{"numbers": [1]}]})
        self.assertIsNot(result["branch.leaf"], leaf)
        result["branch.leaf"][0]["numbers"].append(2)
        self.assertEqual(tree, {"branch": {"leaf": [{"numbers": [1]}]}})

    def test_shared_non_circular_dictionary_is_traversed_at_each_path(self):
        shared = {"value": [1]}
        result = index_leaves({"left": shared, "right": shared})
        self.assertEqual(result, {"left.value": [1], "right.value": [1]})
        self.assertIsNot(result["left.value"], result["right.value"])
        result["left.value"].append(2)
        self.assertEqual(result["right.value"], [1])
        self.assertEqual(shared, {"value": [1]})

    def test_direct_and_indirect_cycles_raise_value_error(self):
        direct = {}
        direct["self"] = direct
        with self.assertRaises(ValueError):
            index_leaves(direct)
        first = {}
        second = {"back": first}
        first["next"] = second
        with self.assertRaises(ValueError):
            index_leaves(first)

    def test_root_and_key_validation(self):
        for root in ([], None, "tree", ()): 
            with self.subTest(root=root):
                with self.assertRaises(TypeError):
                    index_leaves(root)
        for tree in ({1: "value"}, {None: "value"}, {"ok": {2: "value"}}):
            with self.subTest(tree=tree):
                with self.assertRaises(TypeError):
                    index_leaves(tree)
        for tree in ({"": 1}, {"a.b": 1}, {"ok": {"bad.key": 2}}):
            with self.subTest(tree=tree):
                with self.assertRaises(ValueError):
                    index_leaves(tree)


if __name__ == "__main__":
    unittest.main()

